      const move = { line_id: rrS(l.id), ia_line_id: ia, material_id: rrS(l.item_selection), location_id: rrS(ctx.location_id), batch_id: e.batch,
        uom: rrS(l.quantity_uom), from_category: "In Transit" };
      if (e.good > RR_EPS) {
        k++;
        out.toReserved.push(Object.assign({ kind: "TO_RESERVED", quantity: rrQT(e.good), to_category: "Reserved" }, move));
        out.newHoldRows.push(rrRowOf(ctx, ia, l.item_selection, ctx.location_id, e.batch, e.good, l.quantity_uom, k));
        out.iaPicks[ia].push(Object.assign({ material_id: rrS(l.item_selection), location_id: rrS(ctx.location_id), batch_id: e.batch, sm_quantity: rrQT(e.good),
          category: "Unrestricted" }, datesOf[e.batch] || rrDates(null)));
      }
      if (e.defect > RR_EPS) {
        out.toBlocked.push(Object.assign({ kind: "TO_BLOCKED", quantity: rrQT(e.defect), to_category: "Blocked" }, move));
        if (e.batch) detail[e.batch] = rrQT(e.defect);
      }
    }
    out.lineDefects.push({ id: rrS(l.id), defect_qty: rrQT(defectTotal), defect_reason: defectTotal > RR_EPS ? rrS(rc.reason) : "",
      defect_detail: Object.keys(detail).length ? JSON.stringify(detail) : "" });
  }
  return out;
};

// cancel after dispatch (D3): back to the bins and batches it was picked from, reserved for the IA again
const rrCancelBackPlan = function rrCancelBackPlan(lotLines, ctx) {
  const c = ctx || {};
  const out = { ok: true, code: "", message: "", toReserved: [], newHoldRows: [], iaPicks: {} };
  let k = 0;
  for (const l of Array.isArray(lotLines) ? lotLines : []) {
    if (!l || typeof l !== "object") continue;
    const ia = rrS(l.source_ia_line_id);
    out.iaPicks[ia] = out.iaPicks[ia] || [];
    for (const p of rrPicks(l)) {
      k++;
      const material = rrS(p.material_id || l.item_selection);
      out.toReserved.push({ kind: "TO_RESERVED", line_id: rrS(l.id), ia_line_id: ia, material_id: material, from_location_id: rrS(l.location_id),
        location_id: rrS(p.location_id), batch_id: rrS(p.batch_id), quantity: rrQT(p.sm_quantity), uom: rrS(l.quantity_uom), from_category: "In Transit",
        to_category: "Reserved" });
      out.newHoldRows.push(rrRowOf(c, ia, material, p.location_id, p.batch_id, p.sm_quantity, l.quantity_uom, k));
      out.iaPicks[ia].push(Object.assign({ material_id: material, location_id: rrS(p.location_id), batch_id: rrS(p.batch_id), sm_quantity: rrQT(p.sm_quantity),
        category: "Unrestricted" }, rrDates(p)));
    }
  }
  return out;
};

// Report defect (D2): reserved stock at the staging bin -> Blocked (IA-D); the reservation and the IA's picks drop by it
const rrDefectPlan = function rrDefectPlan(iaLines, holdRows, stagingBin, defects) {
  const fail = (code, message) => ({ ok: false, code: code, message: message, moves: [], holdChanges: [], iaPicks: {} });
  const out = { ok: true, code: "", message: "", moves: [], holdChanges: [], iaPicks: {} };
  const list = Array.isArray(iaLines) ? iaLines : [];
  for (let i = 0; i < list.length; i++) {
    const l = list[i] || {};
    const id = rrS(l.id);
    const df = defects && defects[id];
    if (!df || typeof df !== "object") continue;
    const n = i + 1;
    const entries = df.batches && typeof df.batches === "object" ? Object.keys(df.batches).map((b) => ({ batch: b, qty: rrQ8(df.batches[b]) }))
      : [{ batch: rrS(df.batch_id), qty: rrQ8(df.qty) }];
    const total = rrSum(entries, (e) => e.qty);
    if (!(total > RR_EPS)) continue;
    if (!rrS(df.reason)) return fail("IATR_DEFECT_REASON", "Line " + n + ": choose the reason for the defect.");
    const atBin = rrOwnHolds(holdRows, id).filter((h) => rrS(h.bin_location) === rrS(stagingBin));
    let picks = rrPicks(l).map((p) => Object.assign({}, p));
    for (const e of entries) {
      if (e.qty < -RR_EPS) return fail("IATR_DEFECT_TOO_MUCH", "Line " + n + ": a defect can't be negative.");
      const rows = atBin.filter((h) => rrS(h.batch_id) === e.batch);
      const avail = rrSum(rows, (h) => h.open_qty);
      if (e.qty - avail > RR_EPS) return fail("IATR_DEFECT_TOO_MUCH", "Line " + n + ": only " + avail + " reserved at the staging bin" + (e.batch ? " in batch " + e.batch : "") + ".");
      let left = e.qty;
      for (const h of rows) {
        if (!(left > RR_EPS)) break;
        const take = Math.min(rrN(h.open_qty), left);
        const open = rrQ8(rrN(h.open_qty) - take);
        out.holdChanges.push({ id: rrS(h.id), open_qty: rrQT(open), reserved_qty: rrQT(rrN(h.reserved_qty) - take), status: open > RR_EPS ? "Allocated" : "Cancelled" });
        left = rrQ8(left - take);
      }
      out.moves.push({ kind: "DEFECT", line_id: id, material_id: rrS(l.item_selection), location_id: rrS(stagingBin), batch_id: e.batch, quantity: rrQT(e.qty),
        uom: rrS(l.quantity_uom), from_category: "Reserved", to_category: "Blocked", transaction_type: "IA-D" });
      let cut = e.qty;
      picks = picks.map((p) => {
        if (!(cut > RR_EPS) || rrS(p.location_id) !== rrS(stagingBin) || rrS(p.batch_id) !== e.batch) return p;
        const take = Math.min(rrN(p.sm_quantity), cut);
        cut = rrQ8(cut - take);
        return Object.assign({}, p, { sm_quantity: rrQT(rrN(p.sm_quantity) - take) });
      }).filter((p) => rrN(p.sm_quantity) > RR_EPS);
    }
    out.iaPicks[id] = picks;
  }
  return out;
};

// the replacement (D1, D6, D11): per line a request can carry, the demand not yet reserved and not in transit
const rrGap = function rrGap(iaLines, holdRows, requests, items) {
  const transit = {};
  for (const r of Array.isArray(requests) ? requests : []) {
    if (!r || (rrS(r.status) !== "In Progress" && rrS(r.status) !== "Processing")) continue;
    for (const rl of Array.isArray(r.lines) ? r.lines : []) transit[rrS(rl.source_ia_line_id)] = rrQ8((transit[rrS(rl.source_ia_line_id)] || 0) + rrN(rl.requested_qty));
  }
  const out = [];
  for (const l of Array.isArray(iaLines) ? iaLines : []) {
    if (!l || typeof l !== "object") continue;
    const it = items && items[rrS(l.item_selection)];
    if (!rrIsStock(it) || rrIsSerial(it) || rrHasHu(l)) continue;
    const missing = rrQ8(rrDemandOf(l) - rrSum(rrOwnHolds(holdRows, l.id), (h) => h.open_qty) - (transit[rrS(l.id)] || 0));
    if (missing > RR_EPS) out.push({ iaLineId: rrS(l.id), missing: rrQT(missing) });
  }
  return out;
};

// D11: once the IA has used a request (any not cancelled), every line a request can carry is taken from the staging bin; serial and
// handling-unit lines are picked from the warehouse as today
const rrStagingCheck = function rrStagingCheck(iaLines, requests, items, stagingBin) {
  const used = (Array.isArray(requests) ? requests : []).some((r) => r && rrS(r.status) !== "" && rrS(r.status) !== "Cancelled");
  if (!used) return { ok: true, line: 0, message: "" };
  const list = Array.isArray(iaLines) ? iaLines : [];
  for (let i = 0; i < list.length; i++) {
    const l = list[i];
    if (!l || typeof l !== "object") continue;
    const it = items && items[rrS(l.item_selection)];
    if (!rrIsStock(it) || rrIsSerial(it) || rrHasHu(l)) continue;
    if (rrPicks(l).some((p) => rrS(p.location_id) !== rrS(stagingBin))) {
      return { ok: false, line: i + 1, message: "Line " + (i + 1) + " (" + (rrS(l.item_name) || rrS(l.item_selection)) + ") must be taken from the staging bin: "
        + "request a replacement for it." };
    }
  }
  return { ok: true, line: 0, message: "" };
};

// a Created IA's request at dispatch, before the job (SUBMIT): its requested lines as stored; every pick loose Unrestricted stock of
// the line's item, in its unit, away from the staging bin; the picks and the IA's reservation (away from the staging bin) each equal
// to what is requested (rrSwapPlan, which PREPARE runs again on the stored lines under the job)
const rrDispatchCheck = function rrDispatchCheck(stored, incoming, holdRows) {
  const stop = (code, message) => ({ ok: false, code: code, message: message });
  const st = (Array.isArray(stored) ? stored : []).filter((l) => l && typeof l === "object");
  const inc = (Array.isArray(incoming) ? incoming : []).filter((l) => l && typeof l === "object");
  const changed = stop("IATR_DEMAND_CHANGED", "The requested lines of this transfer were changed. Only the picks can be edited: reopen the transfer and pick again.");
  if (!st.length || st.length !== inc.length) return changed;
  const byId = {};
  for (const l of st) byId[rrS(l.id)] = l;
  for (const l of inc) {
    const was = byId[rrS(l.id)];
    if (!was) return changed;
    if (["item_selection", "quantity_uom", "source_ia_line_id", "storage_location_id", "location_id"].some((k) => rrS(l[k]) !== rrS(was[k]))
      || rrQ8(l.requested_qty) !== rrQ8(was.requested_qty)) return changed;
  }
  for (const l of inc) {
    const label = "Line " + (rrS(l.line_index) || rrS(l.id)) + (rrS(l.item_name) ? " (" + rrS(l.item_name) + ")" : "");
    for (const p of rrPicks(l)) {
      if (rrS(p.material_id || l.item_selection) !== rrS(l.item_selection)) return stop("IATR_PICK_ITEM", label + ": a pick is of another item.");
      if (!rrBlank(p.material_uom) && rrS(p.material_uom) !== rrS(l.quantity_uom)) {
        return stop("IATR_PICK_UOM", label + ": pick it in the line's unit; a pick in another unit can't be dispatched.");
      }
      if (rrS(p.handling_unit_id) && rrS(p.handling_unit_id) !== "0") return stop("IATR_PICK_HU", label + ": a pick from a handling unit can't be dispatched; pick loose stock.");
      if ((rrS(p.category) || "Unrestricted") !== "Unrestricted") {
        return stop("IATR_PICK_CATEGORY", label + ": pick Unrestricted stock; " + rrS(p.category) + " stock can't supply production.");
      }
      if (rrS(p.location_id) === rrS(l.location_id)) return stop("IATR_PICK_AT_DESTINATION", label + ": a pick is from the destination bin itself.");
    }
  }
  const sw = rrSwapPlan(inc, holdRows, "");
  return sw.ok ? { ok: true, code: "", message: "" } : stop(sw.code, sw.message);
};

// the Receive's receipts as SUBMIT stores them for PREPARE (part RECEIPTS): one per stored line, the quantities as q8 text, the
// reason as text, per batch when the form sent batches; nothing else of the payload
const rrReceiptsOf = function rrReceiptsOf(lotLines, receipts) {
  const out = {};
  const rec = receipts && typeof receipts === "object" && !Array.isArray(receipts) ? receipts : {};
  for (const l of Array.isArray(lotLines) ? lotLines : []) {
    if (!l || typeof l !== "object") continue;
    const rc = rec[rrS(l.id)];
    if (!rc || typeof rc !== "object" || Array.isArray(rc)) continue;
    const o = { good: rrQT(rc.good), defect: rrQT(rc.defect), reason: rrS(rc.reason) };
    if (rc.batches && typeof rc.batches === "object" && !Array.isArray(rc.batches)) {
      o.batches = {};
      for (const b of Object.keys(rc.batches)) o.batches[rrS(b)] = { good: rrQT((rc.batches[b] || {}).good), defect: rrQT((rc.batches[b] || {}).defect) };
    }
    out[rrS(l.id)] = o;
  }
  return out;
};

// IA -> Location Transfer Request from a reserved Item Assembly (Item Assembly & BOM/TransferRequest/RESERVED_REQUEST_DESIGN.md):
// IA_TRANSFER_REQUEST v8's decisions. Needs iatr_rules.js, iatr_ia.js and iatr_reserve.js before it (iatr_ia.js stays as the IA
// form inlines it).
const IATR_OPS2 = ["CREATE", "REFRESH", "REPLACE", "DEFECT", "CANCEL", "STATUS"];

// RR1: a reserved request's lines as the IA's reservation gives them (line, item, unit, quantity, the reserved bins and batches); the
// request stores it (source_ia_fp), STATUS compares it with the reservation now (stale = refresh)
const rrReqFp = function rrReqFp(reqLines) {
  const rows = (Array.isArray(reqLines) ? reqLines : []).map((l) => [iatrId(l.source_ia_line_id), iatrId(l.item_selection), iatrId(l.quantity_uom), iatrQ8(l.requested_qty).toFixed(8),
    (Array.isArray(l.picks) ? l.picks : []).map((p) => iatrId(p.location_id) + "|" + iatrS(p.batch_id) + "|" + iatrQ8(p.sm_quantity).toFixed(8)).sort()]);
  rows.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return "RR1:" + rows.length + ":" + iatrHash(JSON.stringify(rows));
};

// the request's Location Transfer lines (iatrLotLines' columns): Requested Qty = the reservation, the picks = the reserved bins and
// batches, each with the IA line's own pick there (its balance id and dates); ctx: { iaLines, items, uoms, storage, bin, plant, org }
const rrLotLines = function rrLotLines(reqLines, ctx) {
  const c = ctx || {};
  const byId = {};
  for (const l of Array.isArray(c.iaLines) ? c.iaLines : []) if (l && iatrS(l.id)) byId[iatrId(l.id)] = l;
  const list = Array.isArray(reqLines) ? reqLines : [];
  const base = iatrLotLines(list.map((r) => {
    const src = byId[iatrId(r.source_ia_line_id)] || {};
    return { item_selection: iatrS(r.item_selection), quantity_uom: iatrS(r.quantity_uom), requested_qty: r.requested_qty, source_ia_line_id: iatrS(r.source_ia_line_id),
      source_ref_key: iatrS(src.sc_ref_key), item_name: iatrS(src.item_name) };
  }), c);
  return base.map((row, i) => {
    const r = list[i];
    const own = iatrParse((byId[iatrId(r.source_ia_line_id)] || {}).temp_qty_data).filter((p) => p && typeof p === "object");
    const picks = (Array.isArray(r.picks) ? r.picks : []).map((p) => {
      const m = own.filter((o) => iatrId(o.location_id) === iatrId(p.location_id) && iatrS(o.batch_id) === iatrS(p.batch_id))[0] || {};
      return { material_id: iatrS(r.item_selection), location_id: iatrId(p.location_id), storage_location_id: m.storage_location_id || null, batch_id: iatrS(p.batch_id) || null,
        balance_id: iatrS(m.balance_id), sm_quantity: iatrQ8(p.sm_quantity), category: "Unrestricted", plant_id: iatrId(c.plant), organization_id: iatrId(c.org), is_deleted: 0,
        expired_date: m.expired_date || null, manufacturing_date: m.manufacturing_date || null };
    });
    const total = iatrQ8(picks.reduce((t, p) => t + p.sm_quantity, 0));
    return Object.assign(row, { total_quantity: total.toFixed(8), temp_qty_data: picks.length ? JSON.stringify(picks) : "" });
  });
};

// the IA form's stock summary of a line's picks (sc_main.js scAllocate)
const iatrSummary = function iatrSummary(picks, uom, binName, batchNo) {
  const list = (Array.isArray(picks) ? picks : []).filter((p) => p && typeof p === "object");
  if (!list.length) return "";
  const q = (v) => iatrQ8(v);
  const total = q(list.reduce((t, p) => t + q(p.sm_quantity), 0));
  return "Total: " + total + " " + uom + "\n\nDETAILS:\n" + list.map((p, i) => (i + 1) + ". " + (binName[iatrS(p.location_id)] || iatrS(p.location_id)) + ": " + q(p.sm_quantity) + " "
    + uom + " (UNR)" + (iatrS(p.batch_id) ? "\n[" + (batchNo[iatrS(p.batch_id)] || iatrS(p.batch_id)) + "]" : "")).join("\n");
};

// DEFECT's input: JSON text { <IA line id>: { qty, reason } | { batches: { <batch id>: qty }, reason } } -> { ok, defects } or { ok: false, message }
const iatrDefectsOf = function iatrDefectsOf(text) {
  const bad = (why) => ({ ok: false, message: "defects: " + why });
  let v = null;
  try {
    v = text && typeof text === "object" ? text : JSON.parse(iatrS(text) || "null");
  } catch (e) {
    v = null;
  }
  if (!v || typeof v !== "object" || Array.isArray(v)) return bad("an object of the Item Assembly's line ids");
  const digits = (x) => /^[0-9]{1,20}$/.test(iatrS(x));
  const qty = (x) => iatrS(x) !== "" && isFinite(Number(x)) && Number(x) >= 0;
  const out = {};
  for (const id of Object.keys(v)) {
    const d = v[id];
    if (!digits(id) || !d || typeof d !== "object" || Array.isArray(d)) return bad("line ids (digits) to { qty, reason } or { batches, reason }");
    const o = { reason: iatrS(d.reason) };
    if (o.reason.length > 255) return bad("a reason of at most 255 characters");
    if (d.batches !== undefined) {
      if (!d.batches || typeof d.batches !== "object" || Array.isArray(d.batches)) return bad("batches: batch ids (digits) to quantities");
      o.batches = {};
      for (const b of Object.keys(d.batches)) {
        if (!digits(b) || !qty(d.batches[b])) return bad("batches: batch ids (digits) to quantities of 0 or more");
        o.batches[b] = String(iatrQ8(d.batches[b]));
      }
    } else {
      if (!qty(d.qty)) return bad("qty: a quantity of 0 or more");
      o.qty = String(iatrQ8(d.qty));
    }
    out[id] = o;
  }
  if (!Object.keys(out).length) return bad("at least one line");
  return { ok: true, defects: out };
};

// what an operation may do, from the reads (before any write). inp: iatrDecide's (op, ia, iaLines, items, uoms, reqs, named, sl, bin,
// member, org, iaId, rule, expectFp, storage, binId, requiredDate) + holds (the IA's Allocated RES-01 rows), setupRows (its Item
// Assembly Setup rows), defects (iatrDefectsOf's), now, logEntry (the log entry's who: by, uid, claim), and for the stock summary
// uomNames / binNames / batchNos ->
// { route: ANSWER (code, message, result) | GO (+ the write's values) }
const iatrDecide2 = function iatrDecide2(inp) {
  const x = inp || {};
  const op = iatrS(x.op);
  const ia = x.ia && typeof x.ia === "object" && iatrS(x.ia.id) ? x.ia : null;
  const answer = (code, message, result) => ({ route: "ANSWER", code: String(code), message: message, result: result || {} });
  const reqs = iatrRequests(x.reqs);
  const view = (r) => (r ? { id: iatrS(r.id), no: iatrS(r.no), status: iatrS(r.status), rev: Number(r.rev) || 0 } : null);
  if (IATR_OPS2.indexOf(op) < 0) return answer(400, "operation must be CREATE, REFRESH, REPLACE, DEFECT, CANCEL or STATUS");
  if (!(Number(x.member) > 0)) return answer(400, "You are not assigned to this Item Assembly's organisation.");
  const named = x.named && typeof x.named === "object" ? x.named : null;
  const ours = (n) => n && iatrS(n.id) && iatrS(n.purpose) === IATR_PURPOSE && iatrId(n.source) === iatrId(ia ? ia.id : x.iaId);
  const cancel = (n) => {
    if (iatrS(n.status) === "Cancelled") return answer(200, "Transfer request " + iatrS(n.no) + " is already cancelled.", { request: view(n), already: "YES" });
    if (iatrS(n.status) !== "Requested") {
      return answer(400, "Only a Requested transfer request can be cancelled here (" + iatrS(n.no) + " is " + iatrS(n.status) + "): a dispatched one is cancelled from the Location Transfer list.");
    }
    if (Number(n.openJobs) > 0 || Number(n.openTransit) > 0) return answer(409, "Transfer request " + iatrS(n.no) + " is being dispatched: wait for it to finish.");
    // the IA's link (its list's Transfer Request column: the latest open or received request) goes back to its newest received request
    const back = ia && reqs.received && iatrS(reqs.received.id) !== iatrS(n.id) ? reqs.received : null;
    return { route: "GO", code: "200", message: "", result: {}, lotId: iatrS(n.id), lotNo: iatrS(n.no),
      relink: back ? { id: iatrS(ia.id), transfer_request_id: iatrS(back.id), transfer_request_no: iatrS(back.no) } : null };
  };
  if (!ia) {
    // the IA was deleted with its request live (10-29): that request can still be cancelled, by a user of its own organisation
    if (op !== "CANCEL" || !named) return answer(400, "Item Assembly not found - it may have been deleted.");
    if (!ours(named) || !iatrS(x.iaId)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    if (!iatrS(named.org) || iatrId(named.org) !== iatrId(x.org)) return answer(400, "You are not assigned to this transfer request's organisation.");
    return cancel(named);
  }
  if (iatrId(ia.org) !== iatrId(x.org)) return answer(400, "You are not assigned to this Item Assembly's organisation.");
  const items = {};
  for (const it of Array.isArray(x.items) ? x.items : []) if (it && iatrS(it.id)) items[iatrId(it.id)] = it;
  const holds = Array.isArray(x.holds) ? x.holds : [];
  const setupOn = rrSetupOn(x.setupRows, ia.org);
  const received = reqs.received;
  const staging = received ? { storage: iatrId(received.sl), bin: iatrId(received.bin) } : null;
  const fromHolds = (bin) => {
    const r = rrLinesFromHolds(x.iaLines, holds, items, bin);
    return { lines: r.lines, skipped: r.skipped.filter((k) => k.reason !== "not stock-controlled") };
  };
  const lineCtx = (dest) => ({ iaLines: x.iaLines, items: items, uoms: x.uoms, storage: dest.storage, bin: dest.bin, plant: ia.plant, org: ia.org });
  const status = iatrS(ia.status);
  if (op === "STATUS") {
    const r = reqs.live || received || reqs.latest;
    const stale = r && iatrS(r.status) === "Requested" && status === "Created" ? (rrReqFp(fromHolds(iatrId(r.bin)).lines) !== iatrS(r.fp) ? "YES" : "NO") : "NO";
    return answer(200, "", { request: r ? Object.assign(view(r), { stale: stale, sl: iatrS(r.sl), bin: iatrS(r.bin) }) : null, history: reqs.all.map(view),
      setup_on: setupOn ? "YES" : "NO", can_create: setupOn && status === "Created" && !reqs.live && !received ? "YES" : "NO",
      can_replace: status === "Created" && received && !reqs.live ? "YES" : "NO", staging: staging ? { sl: staging.storage, bin: staging.bin } : null,
      gap: received && !reqs.live ? rrGap(x.iaLines, holds, [], items) : [],
      // the replacement's new reservation is in place (a Created save after its allocation): REPLACE can send it
      replace_ready: status === "Created" && received && !reqs.live && fromHolds(staging.bin).lines.length > 0 ? "YES" : "NO" });
  }
