    const n = x.named && typeof x.named === "object" ? x.named : null;
    if (!n || !iatrS(n.id) || iatrS(n.purpose) !== IATR_PURPOSE || iatrId(n.source) !== iatrId(ia.id)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    return cancel(n);
  }
  // CREATE / REFRESH: a saved Draft IA, nothing held, a positive output, the screen's IA is the stored one, a valid demand
  const status = iatrS(ia.status);
  if (status !== "Draft") return answer(400, "Only a saved Draft Item Assembly can request its materials (this one is " + (status || "without a status") + ").");
  if (IATR_HOLDS_OK.indexOf(iatrS(ia.hold).toUpperCase()) < 0) return answer(400, "This Item Assembly holds materials (" + iatrS(ia.hold) + "): release them first.");
  if (!(iatrQ8(ia.item_qty) > 0)) return answer(400, "Enter the Item Assembly's output quantity and save it, then request its materials.");
  if (iatrS(x.expectFp) !== iatrIaFp(iatrBasis(ia), x.iaLines)) {
    return answer(409, "This Item Assembly has unsaved changes, or someone else saved it: save it (or open it again), then request its materials.");
  }
  const d = demandNow();
  if (!d.ok) return answer(400, d.message);
  if (op === "REFRESH") {
    const n = x.named && typeof x.named === "object" ? x.named : null;
    if (!n || !iatrS(n.id) || iatrS(n.purpose) !== IATR_PURPOSE || iatrId(n.source) !== iatrId(ia.id)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    if (iatrS(n.status) !== "Requested") return answer(400, "Only a Requested transfer request can be refreshed (" + iatrS(n.no) + " is " + iatrS(n.status) + ").");
    if (Number(n.openJobs) > 0 || Number(n.openTransit) > 0) return answer(409, "Transfer request " + iatrS(n.no) + " is being dispatched: wait for it to finish.");
    const dest = destOf(n);
    const fp = fpWith(d, dest);
    const same = iatrDispatchCheck(n.lines, n.lines, { iaStatus: "Draft", iaFp: fp, lotFp: iatrS(n.fp), demand: d.lines });
    if (same.ok || same.code === "IATR_NOT_FULL" || same.code.indexOf("IATR_PICK") === 0) {
      return answer(200, "Transfer request " + iatrS(n.no) + " already matches this Item Assembly.", { request: view(n), already: "YES" });
    }
    return { route: "GO", code: "200", message: "", result: {}, lotId: iatrS(n.id), lotNo: iatrS(n.no), fp: fp, rev: (Number(n.rev) || 0) + 1, lines: d.lines.length,
      lineRows: iatrLotLines(d.lines, { iaLines: x.iaLines, items: items, uoms: x.uoms, storage: dest.storage, bin: dest.bin, plant: ia.plant, org: ia.org }) };
  }
  // CREATE: one live request per IA, never after one was received (spec IA-LT-10); a destination in this plant; a number rule
  if (reqs.live) return answer(200, "This Item Assembly already has transfer request " + iatrS(reqs.live.no) + " (" + iatrS(reqs.live.status) + ").",
    { request: view(reqs.live), existing: "YES" });
  if (reqs.received) {
    return answer(409, "Transfer request " + iatrS(reqs.received.no) + " was already received for this Item Assembly: a second full request can't be made from it.",
      { request: view(reqs.received) });
  }
  const sl = x.sl && typeof x.sl === "object" ? x.sl : null;
  const bin = x.bin && typeof x.bin === "object" ? x.bin : null;
  if (!sl || iatrId(sl.id) !== iatrId(x.storage) || iatrId(sl.plant) !== iatrId(ia.plant) || Number(sl.active) !== 1) {
    return answer(400, "Choose an active storage location of this Item Assembly's plant.");
  }
  if (!bin || iatrId(bin.id) !== iatrId(x.binId) || iatrId(bin.plant) !== iatrId(ia.plant) || iatrId(bin.sl) !== iatrId(sl.id) || Number(bin.active) !== 1) {
    return answer(400, "Choose an active bin of storage location " + (iatrS(sl.name) || iatrS(sl.id)) + ".");
  }
  if (!iatrDate(x.requiredDate)) return answer(400, "Enter the date the materials are required.");
  if (!iatrS(x.rule)) return answer(400, "No Location Transfer number rule is set up for this organisation.");
  const fp = fpWith(d, { storage: iatrId(sl.id), bin: iatrId(bin.id) });
  return { route: "GO", code: "200", message: "", result: {}, fp: fp, rev: 1, lines: d.lines.length, replacesId: reqs.cancelled ? iatrS(reqs.cancelled.id) : "",
    lineRows: iatrLotLines(d.lines, { iaLines: x.iaLines, items: items, uoms: x.uoms, storage: sl.id, bin: bin.id, plant: ia.plant, org: ia.org }) };
};

// after our claim (IA_SAVE MIN-02's rule): the lowest live HELD claim of the IA wins (a claim older than the lease is a dead run), and
// what the decision read must still hold - the IA (CREATE / REFRESH: Draft), no live or received request appeared (CREATE), the named
// request still Requested with no open job (REFRESH / CANCEL). -> { route: WIN | LOSE, message }
const IATR_LEASE_MS = 10 * 60 * 1000;
const iatrWin = function iatrWin(op, ourName, st, lotId) {
  const s0 = st || {};
  const now = Date.parse(iatrS(s0.now).replace(" ", "T") + "Z");
  const claims = (Array.isArray(s0.claims) ? s0.claims : []).filter((c) => c && /^CLAIM\|[0-9]+$/.test(iatrS(c.name)));
  const live = claims.filter((c) => now - Date.parse(iatrS(c.started_at).replace(" ", "T") + "Z") < IATR_LEASE_MS);
  const me = claims.filter((c) => iatrS(c.name) === iatrS(ourName))[0];
  const first = live.slice().sort((a, b) => Number(iatrS(a.name).slice(6)) - Number(iatrS(b.name).slice(6)))[0];
  const lose = (message) => ({ route: "LOSE", claimId: me ? iatrS(me.id) : "", message: message });
  if (!me || !first || iatrS(first.name) !== iatrS(me.name)) return lose("This Item Assembly's transfer request is being changed in another window: refresh it to see the result.");
  if (op !== "CANCEL" && iatrS(s0.status) !== "Draft") return lose("This Item Assembly changed meanwhile (it is " + (iatrS(s0.status) || "gone") + " now): refresh it.");
  const reqs = iatrRequests(s0.reqs);
  if (op === "CREATE" && (reqs.live || reqs.received)) return lose("A transfer request was made for this Item Assembly meanwhile: refresh it.");
  if (op !== "CREATE") {
    const n = reqs.all.filter((r) => iatrS(r.id) === iatrS(lotId))[0];
    if (!n || iatrS(n.status) !== "Requested" || Number(s0.openJobs) > 0) return lose("The transfer request changed meanwhile (it is " + (n ? iatrS(n.status) : "gone") + " now): refresh it.");
  }
  return { route: "WIN", claimId: iatrS(me.id), message: "" };
};

// Reserved transfer requests (Item Assembly & BOM/TransferRequest/RESERVED_REQUEST_DESIGN.md): pure rules shared by
// IA_TRANSFER_REQUEST, LOT V2 SUBMIT / PREPARE / COMMIT, the IA save guard and the IA form. No platform calls.
// Quantities come in as text or numbers and go out as q8 text in the line's unit; ids are text. Reservation rows have RES-01's
// shape (scratchpad/iasc/res01/code/sql_hold.py STATE rows); rows written here carry job_line_key IATR|<lotId>|<k>.
const RR_EPS = 1e-8;
const rrS = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const rrN = (v) => {
  const x = parseFloat(v);
  return isFinite(x) ? x : 0;
};
const rrQ8 = (v) => Number(rrN(v).toFixed(8));
const rrQT = (v) => String(rrQ8(v));
const rrBlank = (v) => rrS(v) === "";
const rrJ = (v) => {
  if (Array.isArray(v)) return v;
  try {
    const x = JSON.parse(rrS(v) || "[]");
    return Array.isArray(x) ? x : [];
  } catch (e) {
    return [];
  }
};
const rrPicks = (l) => rrJ(l && l.temp_qty_data).filter((p) => p && typeof p === "object" && rrN(p.sm_quantity) > RR_EPS);
const rrHasHu = (l) => rrJ(l && l.temp_hu_data).length > 0 || rrPicks(l).some((p) => rrS(p.handling_unit_id) !== "" && rrS(p.handling_unit_id) !== "0");
const rrIsStock = (it) => !!it && Number(it.stock_control) !== 0;
const rrIsSerial = (it) => !!it && Number(it.serial_number_management) === 1;
const rrKey = (bin, batch) => rrS(bin) + "|" + rrS(batch);
const rrLabel = (bin, batch) => (rrS(batch) ? rrS(bin) + " / " + rrS(batch) : rrS(bin));
// the line's live holds; `awayFrom` (a bin) leaves out the holds already there: a request never moves the stock at its own staging bin
const rrOwnHolds = (holdRows, lineId, awayFrom) =>
  (Array.isArray(holdRows) ? holdRows : []).filter((h) => h && typeof h === "object" && rrS(h.status) === "Allocated" && rrS(h.doc_line_id) === rrS(lineId)
    && (rrBlank(awayFrom) || rrS(h.bin_location) !== rrS(awayFrom)));
const rrDates = (p) => ({ expired_date: (p && p.expired_date) || null, manufacturing_date: (p && p.manufacturing_date) || null });
const rrSum = (list, f) => rrQ8(list.reduce((t, x) => t + rrN(f(x)), 0));
// the IA's demand for a line: an explicit requirement (even 0) first, else the BOM reference (the request's own rule, IA-LT-07)
const rrDemandOf = (l) => (!rrBlank(l.required_qty) ? rrQ8(l.required_qty) : rrQ8(l.requested_qty));
const rrRowOf = (ctx, iaLineId, materialId, bin, batch, qty, uom, k) => ({ doc_type: "Item Assembly", status: "Processing", doc_id: rrS(ctx.iaId),
  doc_line_id: rrS(iaLineId), material_id: rrS(materialId), bin_location: rrS(bin), batch_id: rrS(batch), item_uom: rrS(uom), reserved_qty: rrQT(qty),
  open_qty: rrQT(qty), delivered_qty: "0", from_category: "Unrestricted", job_line_key: "IATR|" + rrS(ctx.lotId) + "|" + k });

// D12: the organisation's Item Assembly Setup row (its first one: every plant row carries the same values); no row = off
const rrSetupOn = function rrSetupOn(setupRows, orgId) {
  const row = (Array.isArray(setupRows) ? setupRows : []).find((r) => r && rrS(r.organization_id) === rrS(orgId) && Number(r.is_deleted || 0) === 0);
  return !!row && Number(row.transfer_request_enabled) === 1;
};

// a Created IA's request lines: one per stock line with reserved quantity, its picks = the reservation (D1: partial allowed); serial,
// handling-unit and non-stock lines are never requested; a line with nothing reserved waits for a replacement; the holds already at
// the staging bin (an earlier request's) stay out
const rrLinesFromHolds = function rrLinesFromHolds(iaLines, holdRows, items, stagingBin) {
  const lines = [];
  const skipped = [];
  for (const l of Array.isArray(iaLines) ? iaLines : []) {
    if (!l || typeof l !== "object") continue;
    const id = rrS(l.id);
    const it = items && items[rrS(l.item_selection)];
    if (!rrIsStock(it)) {
      skipped.push({ line: id, reason: "not stock-controlled" });
      continue;
    }
    if (rrIsSerial(it)) {
      skipped.push({ line: id, reason: "serial-numbered: picked from the warehouse as today" });
      continue;
    }
    if (rrHasHu(l)) {
      skipped.push({ line: id, reason: "stock in a handling unit: picked from the warehouse as today" });
      continue;
    }
    const own = rrOwnHolds(holdRows, id, stagingBin).filter((h) => (rrS(h.from_category) || "Unrestricted") === "Unrestricted" && rrS(h.item_uom) === rrS(l.quantity_uom)
      && rrN(h.open_qty) > RR_EPS);
    const held = rrSum(own, (h) => h.open_qty);
    if (!(held > RR_EPS)) {
      skipped.push({ line: id, reason: "nothing reserved: replaced later" });
      continue;
    }
    lines.push({ source_ia_line_id: id, item_selection: rrS(l.item_selection), quantity_uom: rrS(l.quantity_uom), requested_qty: rrQT(held),
      picks: own.map((h) => ({ location_id: rrS(h.bin_location), batch_id: rrS(h.batch_id), sm_quantity: rrQT(h.open_qty), hold_row_id: rrS(h.id) })) });
  }
  return { lines: lines, skipped: skipped };
};

// dispatch: release the IA's reservation for each line and stage the warehouse's picks, in one operation; the released rows are
// cancelled under the operation's marker; a pick away from the reservation names the bins to count
const rrSwapPlan = function rrSwapPlan(lotLines, holdRows, opKey) {
  const marker = "IATR|" + rrS(opKey);
  const fail = (code, message) => ({ ok: false, code: code, message: message, release: [], stage: [], cancelRows: [], countBins: [], marker: marker });
  const out = { ok: true, code: "", message: "", release: [], stage: [], cancelRows: [], countBins: [], marker: marker };
  const list = Array.isArray(lotLines) ? lotLines : [];
  for (let i = 0; i < list.length; i++) {
    const l = list[i] || {};
    const n = i + 1;
    const want = rrQ8(l.requested_qty);
    const picks = rrPicks(l);
    const picked = rrSum(picks, (p) => p.sm_quantity);
    if (Math.abs(picked - want) > RR_EPS) return fail("IATR_PICKS_SHORT", "Line " + n + ": " + picked + " picked for " + want + " requested.");
    const own = rrOwnHolds(holdRows, l.source_ia_line_id, l.location_id);
    const held = rrSum(own, (h) => h.open_qty);
    if (Math.abs(held - want) > RR_EPS || own.some((h) => (rrS(h.from_category) || "Unrestricted") !== "Unrestricted")) {
      return fail("IATR_HOLD_STALE", "Line " + n + ": the Item Assembly's reservation changed (" + held + " reserved for " + want
        + " requested): refresh the request from the Item Assembly.");
    }
    const heldAt = {};
    const labelOf = {};
    for (const h of own) {
      out.release.push({ kind: "RELEASE", line_id: rrS(l.id), ia_line_id: rrS(l.source_ia_line_id), material_id: rrS(h.material_id || l.item_selection),
        location_id: rrS(h.bin_location), batch_id: rrS(h.batch_id), quantity: rrQT(h.open_qty), uom: rrS(h.item_uom || l.quantity_uom),
        from_category: "Reserved", to_category: "Unrestricted", hold_row_id: rrS(h.id) });
      out.cancelRows.push(rrS(h.id));
      const k = rrKey(h.bin_location, h.batch_id);
      heldAt[k] = rrQ8((heldAt[k] || 0) + rrN(h.open_qty));
      labelOf[k] = rrLabel(h.bin_location, h.batch_id);
    }
    const pickedAt = {};
    for (const p of picks) {
      out.stage.push({ kind: "STAGE", line_id: rrS(l.id), ia_line_id: rrS(l.source_ia_line_id), material_id: rrS(p.material_id || l.item_selection),
        location_id: rrS(p.location_id), batch_id: rrS(p.batch_id), to_location_id: rrS(l.location_id), quantity: rrQT(p.sm_quantity), uom: rrS(l.quantity_uom),
        from_category: "Unrestricted", to_category: "In Transit" });
      const k = rrKey(p.location_id, p.batch_id);
      pickedAt[k] = rrQ8((pickedAt[k] || 0) + rrN(p.sm_quantity));
      labelOf[k] = labelOf[k] || rrLabel(p.location_id, p.batch_id);
    }
    const reservedAt = Object.keys(heldAt).filter((k) => heldAt[k] - (pickedAt[k] || 0) > RR_EPS).map((k) => labelOf[k]);
    for (const k of Object.keys(pickedAt)) {
      if (pickedAt[k] - (heldAt[k] || 0) > RR_EPS) out.countBins.push({ line: n, item: rrS(l.item_selection), pickedFrom: labelOf[k], reservedAt: reservedAt });
    }
  }
  return out;
};

// Receive (D5, D7, D10): good + defect = what was dispatched, per batch for a line that came in several batches; good lands Reserved
// for the IA at the staging bin (new rows, the IA's picks there), defect lands Blocked with its reason
const rrReceivePlan = function rrReceivePlan(lotLines, receipts, dest) {
  const ctx = dest || {};
  const fail = (code, message) => ({ ok: false, code: code, message: message, toReserved: [], toBlocked: [], newHoldRows: [], iaPicks: {}, lineDefects: [] });
  const out = { ok: true, code: "", message: "", toReserved: [], toBlocked: [], newHoldRows: [], iaPicks: {}, lineDefects: [] };
  const list = Array.isArray(lotLines) ? lotLines : [];
  let k = 0;
  for (let i = 0; i < list.length; i++) {
    const l = list[i] || {};
    const n = i + 1;
    const ia = rrS(l.source_ia_line_id);
    const byBatch = {};
    const datesOf = {};
    for (const p of rrPicks(l)) {
      byBatch[rrS(p.batch_id)] = rrQ8((byBatch[rrS(p.batch_id)] || 0) + rrN(p.sm_quantity));
      if (!datesOf[rrS(p.batch_id)] || (!datesOf[rrS(p.batch_id)].expired_date && !datesOf[rrS(p.batch_id)].manufacturing_date)) datesOf[rrS(p.batch_id)] = rrDates(p);
    }
    const batches = Object.keys(byBatch);
    const rc = receipts && receipts[rrS(l.id)];
    if (!rc || typeof rc !== "object") return fail("IATR_RECEIPT_INVALID", "Line " + n + ": enter the good and defect quantities.");
    let entries;
    if (rc.batches && typeof rc.batches === "object") {
      if (Object.keys(rc.batches).some((b) => byBatch[b] === undefined)) return fail("IATR_RECEIPT_INVALID", "Line " + n + ": a batch that wasn't dispatched.");
      entries = batches.map((b) => ({ batch: b, good: rrQ8((rc.batches[b] || {}).good), defect: rrQ8((rc.batches[b] || {}).defect) }));
    } else {
      if (batches.length > 1) return fail("IATR_RECEIPT_INVALID", "Line " + n + ": enter the good and defect quantities per batch.");
      entries = [{ batch: batches[0] || "", good: rrQ8(rc.good), defect: rrQ8(rc.defect) }];
    }
    for (const e of entries) {
      if (e.good < -RR_EPS || e.defect < -RR_EPS || Math.abs(e.good + e.defect - (byBatch[e.batch] || 0)) > RR_EPS) {
        return fail("IATR_RECEIPT_INVALID", "Line " + n + ": good + defect must equal the " + (byBatch[e.batch] || 0) + " dispatched"
          + (e.batch ? " in batch " + e.batch : "") + ".");
      }
    }
    const defectTotal = rrSum(entries, (e) => e.defect);
    if (defectTotal > RR_EPS && !rrS(rc.reason)) return fail("IATR_DEFECT_REASON", "Line " + n + ": choose the reason for the defect.");
    out.iaPicks[ia] = out.iaPicks[ia] || [];
    const detail = {};
    for (const e of entries) {
      const move = { line_id: rrS(l.id), ia_line_id: ia, material_id: rrS(l.item_selection), location_id: rrS(ctx.location_id), batch_id: e.batch,
        uom: rrS(l.quantity_uom), from_category: "In Transit" };
      if (e.good > RR_EPS) {
        k++;
        out.toReserved.push(Object.assign({ kind: "TO_RESERVED", quantity: rrQT(e.good), to_category: "Reserved" }, move));
        out.newHoldRows.push(rrRowOf(ctx, ia, l.item_selection, ctx.location_id, e.batch, e.good, l.quantity_uom, k));
        out.iaPicks[ia].push(Object.assign({ material_id: rrS(l.item_selection), location_id: rrS(ctx.location_id), batch_id: e.batch, sm_quantity: rrQT(e.good),
          category: "Unrestricted" }, datesOf[e.batch] || rrDates(null)));
      }
      if (e.defect > RR_EPS) {
        out.toBlocked.push(Object.assign({ kind: "TO_BLOCKED", quantity: rrQT(e.defect), to_category: "Blocked" }, move));
        if (e.batch) detail[e.batch] = rrQT(e.defect);
      }
    }
    out.lineDefects.push({ id: rrS(l.id), defect_qty: rrQT(defectTotal), defect_reason: defectTotal > RR_EPS ? rrS(rc.reason) : "",
      defect_detail: Object.keys(detail).length ? JSON.stringify(detail) : "" });
  }
  return out;
};

// cancel after dispatch (D3): back to the bins and batches it was picked from, reserved for the IA again
const rrCancelBackPlan = function rrCancelBackPlan(lotLines, ctx) {
  const c = ctx || {};
  const out = { ok: true, code: "", message: "", toReserved: [], newHoldRows: [], iaPicks: {} };
  let k = 0;
  for (const l of Array.isArray(lotLines) ? lotLines : []) {
    if (!l || typeof l !== "object") continue;
    const ia = rrS(l.source_ia_line_id);
    out.iaPicks[ia] = out.iaPicks[ia] || [];
    for (const p of rrPicks(l)) {
      k++;
      const material = rrS(p.material_id || l.item_selection);
      out.toReserved.push({ kind: "TO_RESERVED", line_id: rrS(l.id), ia_line_id: ia, material_id: material, from_location_id: rrS(l.location_id),
        location_id: rrS(p.location_id), batch_id: rrS(p.batch_id), quantity: rrQT(p.sm_quantity), uom: rrS(l.quantity_uom), from_category: "In Transit",
        to_category: "Reserved" });
      out.newHoldRows.push(rrRowOf(c, ia, material, p.location_id, p.batch_id, p.sm_quantity, l.quantity_uom, k));
      out.iaPicks[ia].push(Object.assign({ material_id: material, location_id: rrS(p.location_id), batch_id: rrS(p.batch_id), sm_quantity: rrQT(p.sm_quantity),
        category: "Unrestricted" }, rrDates(p)));
    }
  }
  return out;
};

// Report defect (D2): reserved stock at the staging bin -> Blocked (IA-D); the reservation and the IA's picks drop by it
const rrDefectPlan = function rrDefectPlan(iaLines, holdRows, stagingBin, defects) {
  const fail = (code, message) => ({ ok: false, code: code, message: message, moves: [], holdChanges: [], iaPicks: {} });
  const out = { ok: true, code: "", message: "", moves: [], holdChanges: [], iaPicks: {} };
  const list = Array.isArray(iaLines) ? iaLines : [];
  for (let i = 0; i < list.length; i++) {
    const l = list[i] || {};
    const id = rrS(l.id);
    const df = defects && defects[id];
    if (!df || typeof df !== "object") continue;
    const n = i + 1;
    const entries = df.batches && typeof df.batches === "object" ? Object.keys(df.batches).map((b) => ({ batch: b, qty: rrQ8(df.batches[b]) }))
      : [{ batch: rrS(df.batch_id), qty: rrQ8(df.qty) }];
    const total = rrSum(entries, (e) => e.qty);
    if (!(total > RR_EPS)) continue;
    if (!rrS(df.reason)) return fail("IATR_DEFECT_REASON", "Line " + n + ": choose the reason for the defect.");
    const atBin = rrOwnHolds(holdRows, id).filter((h) => rrS(h.bin_location) === rrS(stagingBin));
    let picks = rrPicks(l).map((p) => Object.assign({}, p));
    for (const e of entries) {
      if (e.qty < -RR_EPS) return fail("IATR_DEFECT_TOO_MUCH", "Line " + n + ": a defect can't be negative.");
      const rows = atBin.filter((h) => rrS(h.batch_id) === e.batch);
      const avail = rrSum(rows, (h) => h.open_qty);
      if (e.qty - avail > RR_EPS) return fail("IATR_DEFECT_TOO_MUCH", "Line " + n + ": only " + avail + " reserved at the staging bin" + (e.batch ? " in batch " + e.batch : "") + ".");
      let left = e.qty;
      for (const h of rows) {
        if (!(left > RR_EPS)) break;
        const take = Math.min(rrN(h.open_qty), left);
        const open = rrQ8(rrN(h.open_qty) - take);
        out.holdChanges.push({ id: rrS(h.id), open_qty: rrQT(open), reserved_qty: rrQT(rrN(h.reserved_qty) - take), status: open > RR_EPS ? "Allocated" : "Cancelled" });
        left = rrQ8(left - take);
      }
      out.moves.push({ kind: "DEFECT", line_id: id, material_id: rrS(l.item_selection), location_id: rrS(stagingBin), batch_id: e.batch, quantity: rrQT(e.qty),
        uom: rrS(l.quantity_uom), from_category: "Reserved", to_category: "Blocked", transaction_type: "IA-D" });
      let cut = e.qty;
      picks = picks.map((p) => {
        if (!(cut > RR_EPS) || rrS(p.location_id) !== rrS(stagingBin) || rrS(p.batch_id) !== e.batch) return p;
        const take = Math.min(rrN(p.sm_quantity), cut);
        cut = rrQ8(cut - take);
        return Object.assign({}, p, { sm_quantity: rrQT(rrN(p.sm_quantity) - take) });
      }).filter((p) => rrN(p.sm_quantity) > RR_EPS);
    }
    out.iaPicks[id] = picks;
  }
  return out;
};

// the replacement (D1, D6, D11): per line a request can carry, the demand not yet reserved and not in transit
const rrGap = function rrGap(iaLines, holdRows, requests, items) {
  const transit = {};
  for (const r of Array.isArray(requests) ? requests : []) {
    if (!r || (rrS(r.status) !== "In Progress" && rrS(r.status) !== "Processing")) continue;
    for (const rl of Array.isArray(r.lines) ? r.lines : []) transit[rrS(rl.source_ia_line_id)] = rrQ8((transit[rrS(rl.source_ia_line_id)] || 0) + rrN(rl.requested_qty));
  }
  const out = [];
  for (const l of Array.isArray(iaLines) ? iaLines : []) {
    if (!l || typeof l !== "object") continue;
    const it = items && items[rrS(l.item_selection)];
    if (!rrIsStock(it) || rrIsSerial(it) || rrHasHu(l)) continue;
    const missing = rrQ8(rrDemandOf(l) - rrSum(rrOwnHolds(holdRows, l.id), (h) => h.open_qty) - (transit[rrS(l.id)] || 0));
    if (missing > RR_EPS) out.push({ iaLineId: rrS(l.id), missing: rrQT(missing) });
  }
  return out;
};

// D11: once the IA has used a request (any not cancelled), every line a request can carry is taken from the staging bin; serial and
// handling-unit lines are picked from the warehouse as today
const rrStagingCheck = function rrStagingCheck(iaLines, requests, items, stagingBin) {
  const used = (Array.isArray(requests) ? requests : []).some((r) => r && rrS(r.status) !== "" && rrS(r.status) !== "Cancelled");
  if (!used) return { ok: true, line: 0, message: "" };
  const list = Array.isArray(iaLines) ? iaLines : [];
  for (let i = 0; i < list.length; i++) {
    const l = list[i];
    if (!l || typeof l !== "object") continue;
    const it = items && items[rrS(l.item_selection)];
    if (!rrIsStock(it) || rrIsSerial(it) || rrHasHu(l)) continue;
    if (rrPicks(l).some((p) => rrS(p.location_id) !== rrS(stagingBin))) {
      return { ok: false, line: i + 1, message: "Line " + (i + 1) + " (" + (rrS(l.item_name) || rrS(l.item_selection)) + ") must be taken from the staging bin: "
        + "request a replacement for it." };
    }
  }
  return { ok: true, line: 0, message: "" };
};

// a Created IA's request at dispatch, before the job (SUBMIT): its requested lines as stored; every pick loose Unrestricted stock of
// the line's item, in its unit, away from the staging bin; the picks and the IA's reservation (away from the staging bin) each equal
// to what is requested (rrSwapPlan, which PREPARE runs again on the stored lines under the job)
const rrDispatchCheck = function rrDispatchCheck(stored, incoming, holdRows) {
  const stop = (code, message) => ({ ok: false, code: code, message: message });
  const st = (Array.isArray(stored) ? stored : []).filter((l) => l && typeof l === "object");
  const inc = (Array.isArray(incoming) ? incoming : []).filter((l) => l && typeof l === "object");
  const changed = stop("IATR_DEMAND_CHANGED", "The requested lines of this transfer were changed. Only the picks can be edited: reopen the transfer and pick again.");
  if (!st.length || st.length !== inc.length) return changed;
  const byId = {};
  for (const l of st) byId[rrS(l.id)] = l;
  for (const l of inc) {
    const was = byId[rrS(l.id)];
    if (!was) return changed;
    if (["item_selection", "quantity_uom", "source_ia_line_id", "storage_location_id", "location_id"].some((k) => rrS(l[k]) !== rrS(was[k]))
      || rrQ8(l.requested_qty) !== rrQ8(was.requested_qty)) return changed;
  }
  for (const l of inc) {
    const label = "Line " + (rrS(l.line_index) || rrS(l.id)) + (rrS(l.item_name) ? " (" + rrS(l.item_name) + ")" : "");
    for (const p of rrPicks(l)) {
      if (rrS(p.material_id || l.item_selection) !== rrS(l.item_selection)) return stop("IATR_PICK_ITEM", label + ": a pick is of another item.");
      if (!rrBlank(p.material_uom) && rrS(p.material_uom) !== rrS(l.quantity_uom)) {
        return stop("IATR_PICK_UOM", label + ": pick it in the line's unit; a pick in another unit can't be dispatched.");
      }
      if (rrS(p.handling_unit_id) && rrS(p.handling_unit_id) !== "0") return stop("IATR_PICK_HU", label + ": a pick from a handling unit can't be dispatched; pick loose stock.");
      if ((rrS(p.category) || "Unrestricted") !== "Unrestricted") {
        return stop("IATR_PICK_CATEGORY", label + ": pick Unrestricted stock; " + rrS(p.category) + " stock can't supply production.");
      }
      if (rrS(p.location_id) === rrS(l.location_id)) return stop("IATR_PICK_AT_DESTINATION", label + ": a pick is from the destination bin itself.");
    }
  }
  const sw = rrSwapPlan(inc, holdRows, "");
  return sw.ok ? { ok: true, code: "", message: "" } : stop(sw.code, sw.message);
};

// the Receive's receipts as SUBMIT stores them for PREPARE (part RECEIPTS): one per stored line, the quantities as q8 text, the
// reason as text, per batch when the form sent batches; nothing else of the payload
const rrReceiptsOf = function rrReceiptsOf(lotLines, receipts) {
  const out = {};
  const rec = receipts && typeof receipts === "object" && !Array.isArray(receipts) ? receipts : {};
  for (const l of Array.isArray(lotLines) ? lotLines : []) {
    if (!l || typeof l !== "object") continue;
    const rc = rec[rrS(l.id)];
    if (!rc || typeof rc !== "object" || Array.isArray(rc)) continue;
    const o = { good: rrQT(rc.good), defect: rrQT(rc.defect), reason: rrS(rc.reason) };
    if (rc.batches && typeof rc.batches === "object" && !Array.isArray(rc.batches)) {
      o.batches = {};
      for (const b of Object.keys(rc.batches)) o.batches[rrS(b)] = { good: rrQT((rc.batches[b] || {}).good), defect: rrQT((rc.batches[b] || {}).defect) };
    }
    out[rrS(l.id)] = o;
  }
  return out;
};

// IA -> Location Transfer Request from a reserved Item Assembly (Item Assembly & BOM/TransferRequest/RESERVED_REQUEST_DESIGN.md):
// IA_TRANSFER_REQUEST v8's decisions. Needs iatr_rules.js, iatr_ia.js and iatr_reserve.js before it (iatr_ia.js stays as the IA
// form inlines it).
const IATR_OPS2 = ["CREATE", "REFRESH", "REPLACE", "DEFECT", "CANCEL", "STATUS"];

// RR1: a reserved request's lines as the IA's reservation gives them (line, item, unit, quantity, the reserved bins and batches); the
// request stores it (source_ia_fp), STATUS compares it with the reservation now (stale = refresh)
const rrReqFp = function rrReqFp(reqLines) {
  const rows = (Array.isArray(reqLines) ? reqLines : []).map((l) => [iatrId(l.source_ia_line_id), iatrId(l.item_selection), iatrId(l.quantity_uom), iatrQ8(l.requested_qty).toFixed(8),
    (Array.isArray(l.picks) ? l.picks : []).map((p) => iatrId(p.location_id) + "|" + iatrS(p.batch_id) + "|" + iatrQ8(p.sm_quantity).toFixed(8)).sort()]);
  rows.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return "RR1:" + rows.length + ":" + iatrHash(JSON.stringify(rows));
};

// the request's Location Transfer lines (iatrLotLines' columns): Requested Qty = the reservation, the picks = the reserved bins and
// batches, each with the IA line's own pick there (its balance id and dates); ctx: { iaLines, items, uoms, storage, bin, plant, org }
const rrLotLines = function rrLotLines(reqLines, ctx) {
  const c = ctx || {};
  const byId = {};
  for (const l of Array.isArray(c.iaLines) ? c.iaLines : []) if (l && iatrS(l.id)) byId[iatrId(l.id)] = l;
  const list = Array.isArray(reqLines) ? reqLines : [];
  const base = iatrLotLines(list.map((r) => {
    const src = byId[iatrId(r.source_ia_line_id)] || {};
    return { item_selection: iatrS(r.item_selection), quantity_uom: iatrS(r.quantity_uom), requested_qty: r.requested_qty, source_ia_line_id: iatrS(r.source_ia_line_id),
      source_ref_key: iatrS(src.sc_ref_key), item_name: iatrS(src.item_name) };
  }), c);
  return base.map((row, i) => {
    const r = list[i];
    const own = iatrParse((byId[iatrId(r.source_ia_line_id)] || {}).temp_qty_data).filter((p) => p && typeof p === "object");
    const picks = (Array.isArray(r.picks) ? r.picks : []).map((p) => {
      const m = own.filter((o) => iatrId(o.location_id) === iatrId(p.location_id) && iatrS(o.batch_id) === iatrS(p.batch_id))[0] || {};
      return { material_id: iatrS(r.item_selection), location_id: iatrId(p.location_id), storage_location_id: m.storage_location_id || null, batch_id: iatrS(p.batch_id) || null,
        balance_id: iatrS(m.balance_id), sm_quantity: iatrQ8(p.sm_quantity), category: "Unrestricted", plant_id: iatrId(c.plant), organization_id: iatrId(c.org), is_deleted: 0,
        expired_date: m.expired_date || null, manufacturing_date: m.manufacturing_date || null };
    });
    const total = iatrQ8(picks.reduce((t, p) => t + p.sm_quantity, 0));
    return Object.assign(row, { total_quantity: total.toFixed(8), temp_qty_data: picks.length ? JSON.stringify(picks) : "" });
  });
};

// the IA form's stock summary of a line's picks (sc_main.js scAllocate)
const iatrSummary = function iatrSummary(picks, uom, binName, batchNo) {
  const list = (Array.isArray(picks) ? picks : []).filter((p) => p && typeof p === "object");
  if (!list.length) return "";
  const q = (v) => iatrQ8(v);
  const total = q(list.reduce((t, p) => t + q(p.sm_quantity), 0));
  return "Total: " + total + " " + uom + "\n\nDETAILS:\n" + list.map((p, i) => (i + 1) + ". " + (binName[iatrS(p.location_id)] || iatrS(p.location_id)) + ": " + q(p.sm_quantity) + " "
    + uom + " (UNR)" + (iatrS(p.batch_id) ? "\n[" + (batchNo[iatrS(p.batch_id)] || iatrS(p.batch_id)) + "]" : "")).join("\n");
};

// DEFECT's input: JSON text { <IA line id>: { qty, reason } | { batches: { <batch id>: qty }, reason } } -> { ok, defects } or { ok: false, message }
const iatrDefectsOf = function iatrDefectsOf(text) {
  const bad = (why) => ({ ok: false, message: "defects: " + why });
  let v = null;
  try {
    v = text && typeof text === "object" ? text : JSON.parse(iatrS(text) || "null");
  } catch (e) {
    v = null;
  }
  if (!v || typeof v !== "object" || Array.isArray(v)) return bad("an object of the Item Assembly's line ids");
  const digits = (x) => /^[0-9]{1,20}$/.test(iatrS(x));
  const qty = (x) => iatrS(x) !== "" && isFinite(Number(x)) && Number(x) >= 0;
  const out = {};
  for (const id of Object.keys(v)) {
    const d = v[id];
    if (!digits(id) || !d || typeof d !== "object" || Array.isArray(d)) return bad("line ids (digits) to { qty, reason } or { batches, reason }");
    const o = { reason: iatrS(d.reason) };
    if (o.reason.length > 255) return bad("a reason of at most 255 characters");
    if (d.batches !== undefined) {
      if (!d.batches || typeof d.batches !== "object" || Array.isArray(d.batches)) return bad("batches: batch ids (digits) to quantities");
      o.batches = {};
      for (const b of Object.keys(d.batches)) {
        if (!digits(b) || !qty(d.batches[b])) return bad("batches: batch ids (digits) to quantities of 0 or more");
        o.batches[b] = String(iatrQ8(d.batches[b]));
      }
    } else {
      if (!qty(d.qty)) return bad("qty: a quantity of 0 or more");
      o.qty = String(iatrQ8(d.qty));
    }
    out[id] = o;
  }
  if (!Object.keys(out).length) return bad("at least one line");
  return { ok: true, defects: out };
};

// what an operation may do, from the reads (before any write). inp: iatrDecide's (op, ia, iaLines, items, uoms, reqs, named, sl, bin,
// member, org, iaId, rule, expectFp, storage, binId, requiredDate) + holds (the IA's Allocated RES-01 rows), setupRows (its Item
// Assembly Setup rows), defects (iatrDefectsOf's), now, logEntry (the log entry's who: by, uid, claim), and for the stock summary
// uomNames / binNames / batchNos ->
// { route: ANSWER (code, message, result) | GO (+ the write's values) }
const iatrDecide2 = function iatrDecide2(inp) {
  const x = inp || {};
  const op = iatrS(x.op);
  const ia = x.ia && typeof x.ia === "object" && iatrS(x.ia.id) ? x.ia : null;
  const answer = (code, message, result) => ({ route: "ANSWER", code: String(code), message: message, result: result || {} });
  const reqs = iatrRequests(x.reqs);
  const view = (r) => (r ? { id: iatrS(r.id), no: iatrS(r.no), status: iatrS(r.status), rev: Number(r.rev) || 0 } : null);
  if (IATR_OPS2.indexOf(op) < 0) return answer(400, "operation must be CREATE, REFRESH, REPLACE, DEFECT, CANCEL or STATUS");
  if (!(Number(x.member) > 0)) return answer(400, "You are not assigned to this Item Assembly's organisation.");
  const named = x.named && typeof x.named === "object" ? x.named : null;
  const ours = (n) => n && iatrS(n.id) && iatrS(n.purpose) === IATR_PURPOSE && iatrId(n.source) === iatrId(ia ? ia.id : x.iaId);
  const cancel = (n) => {
    if (iatrS(n.status) === "Cancelled") return answer(200, "Transfer request " + iatrS(n.no) + " is already cancelled.", { request: view(n), already: "YES" });
    if (iatrS(n.status) !== "Requested") {
      return answer(400, "Only a Requested transfer request can be cancelled here (" + iatrS(n.no) + " is " + iatrS(n.status) + "): a dispatched one is cancelled from the Location Transfer list.");
    }
    if (Number(n.openJobs) > 0 || Number(n.openTransit) > 0) return answer(409, "Transfer request " + iatrS(n.no) + " is being dispatched: wait for it to finish.");
    // the IA's link (its list's Transfer Request column: the latest open or received request) goes back to its newest received request
    const back = ia && reqs.received && iatrS(reqs.received.id) !== iatrS(n.id) ? reqs.received : null;
    return { route: "GO", code: "200", message: "", result: {}, lotId: iatrS(n.id), lotNo: iatrS(n.no),
      relink: back ? { id: iatrS(ia.id), transfer_request_id: iatrS(back.id), transfer_request_no: iatrS(back.no) } : null };
  };
  if (!ia) {
    // the IA was deleted with its request live (10-29): that request can still be cancelled, by a user of its own organisation
    if (op !== "CANCEL" || !named) return answer(400, "Item Assembly not found - it may have been deleted.");
    if (!ours(named) || !iatrS(x.iaId)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    if (!iatrS(named.org) || iatrId(named.org) !== iatrId(x.org)) return answer(400, "You are not assigned to this transfer request's organisation.");
    return cancel(named);
  }
  if (iatrId(ia.org) !== iatrId(x.org)) return answer(400, "You are not assigned to this Item Assembly's organisation.");
  const items = {};
  for (const it of Array.isArray(x.items) ? x.items : []) if (it && iatrS(it.id)) items[iatrId(it.id)] = it;
  const holds = Array.isArray(x.holds) ? x.holds : [];
  const setupOn = rrSetupOn(x.setupRows, ia.org);
  const received = reqs.received;
  const staging = received ? { storage: iatrId(received.sl), bin: iatrId(received.bin) } : null;
  const fromHolds = (bin) => {
    const r = rrLinesFromHolds(x.iaLines, holds, items, bin);
    return { lines: r.lines, skipped: r.skipped.filter((k) => k.reason !== "not stock-controlled") };
  };
  const lineCtx = (dest) => ({ iaLines: x.iaLines, items: items, uoms: x.uoms, storage: dest.storage, bin: dest.bin, plant: ia.plant, org: ia.org });
  const status = iatrS(ia.status);
  if (op === "STATUS") {
    const r = reqs.live || received || reqs.latest;
    const stale = r && iatrS(r.status) === "Requested" && status === "Created" ? (rrReqFp(fromHolds(iatrId(r.bin)).lines) !== iatrS(r.fp) ? "YES" : "NO") : "NO";
    return answer(200, "", { request: r ? Object.assign(view(r), { stale: stale, sl: iatrS(r.sl), bin: iatrS(r.bin) }) : null, history: reqs.all.map(view),
      setup_on: setupOn ? "YES" : "NO", can_create: setupOn && status === "Created" && !reqs.live && !received ? "YES" : "NO",
      can_replace: status === "Created" && received && !reqs.live ? "YES" : "NO", staging: staging ? { sl: staging.storage, bin: staging.bin } : null,
      gap: received && !reqs.live ? rrGap(x.iaLines, holds, [], items) : [],
      // the replacement's new reservation is in place (a Created save after its allocation): REPLACE can send it
      replace_ready: status === "Created" && received && !reqs.live && fromHolds(staging.bin).lines.length > 0 ? "YES" : "NO" });
  }
  if (op === "CANCEL") {
    if (!ours(named)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    return cancel(named);
  }
  // CREATE / REFRESH / REPLACE / DEFECT: a Created IA, whose components RES-01 reserved (a Draft reserves nothing)
  if (status !== "Created") {
    return answer(400, "Only a Created Item Assembly can use transfer requests: save it as Created first, which reserves its materials (this one is " + (status || "without a status") + ").");
  }
  if (op !== "DEFECT" && iatrS(x.expectFp) !== iatrIaFp(iatrBasis(ia), x.iaLines)) {
    return answer(409, "This Item Assembly has unsaved changes, or someone else saved it: save it (or open it again), then try again.");
  }
  if (op === "DEFECT") {
    if (!received) return answer(400, "Report a defect after a transfer request is received: nothing of this Item Assembly is reserved at a staging bin yet.");
    const d = rrDefectPlan(x.iaLines, holds, staging.bin, x.defects);
    if (!d.ok) return answer(400, d.message, { code: d.code });
    if (!d.moves.length) return answer(400, "Enter the defective quantity of at least one line.");
    const map = (rows, k, v) => {
      const o = {};
      for (const r of Array.isArray(rows) ? rows : []) if (r && iatrS(r.id)) o[iatrS(r.id)] = iatrS(r[v]);
      return o;
    };
    const uomName = map(x.uomNames, "id", "uom_name");
    const binName = map(x.binNames, "id", "name");
    const batchNo = map(x.batchNos, "id", "batch_number");
    const byLine = {};
    for (const l of Array.isArray(x.iaLines) ? x.iaLines : []) if (l && iatrS(l.id)) byLine[iatrS(l.id)] = l;
    const movements = [];
    d.moves.forEach((m, i) => {
      const k = "D" + (i + 1);
      const base = { material_id: iatrS(m.material_id), location_id: iatrS(m.location_id), batch_id: iatrS(m.batch_id) || null, plant_id: iatrS(ia.plant), organization_id: iatrS(ia.org),
        quantity: iatrQ8(m.quantity), material_uom: iatrS(m.uom) || null, isMovingInv: 1, transaction_type: "IA-D", trx_no: iatrS(ia.no) + "/D", parent_trx_no: "",
        doc_date: iatrS(x.now) || null };
      movements.push(Object.assign({ movement_key: k, direction: "SUBTRACT", inventory_category: "Reserved" }, base));
      movements.push(Object.assign({ movement_key: k + ".2", direction: "ADD", inventory_category: "Blocked" }, base, { unit_price_from: k }));
    });
    const iaRows = Object.keys(d.iaPicks).map((id) => {
      const picks = d.iaPicks[id].map((p) => Object.assign({}, p, { sm_quantity: iatrQ8(p.sm_quantity) }));
      return { id: id, temp_qty_data: picks.length ? JSON.stringify(picks) : "", total_quantity: iatrQ8(picks.reduce((t, p) => t + p.sm_quantity, 0)).toFixed(8),
        stock_summary: iatrSummary(picks, uomName[iatrS((byLine[id] || {}).quantity_uom)] || "", binName, batchNo) };
    });
    const entry = Object.assign({ at: iatrS(x.now) }, x.logEntry || {}, { op: "DEFECT", defects: x.defects });
    return { route: "GO", code: "200", message: "", result: {}, lotId: iatrS(received.id), lotNo: iatrS(received.no), defect: d, movements: movements, iaRows: iaRows,
      holdRows: d.holdChanges, logRow: { id: iatrS(received.id), request_log: iatrLog(received.log, entry) } };
  }
  if (op === "REFRESH") {
    if (!ours(named)) return answer(400, "This transfer request does not belong to this Item Assembly.");
    if (iatrS(named.status) !== "Requested") return answer(400, "Only a Requested transfer request can be refreshed (" + iatrS(named.no) + " is " + iatrS(named.status) + ").");
    if (Number(named.openJobs) > 0 || Number(named.openTransit) > 0) return answer(409, "Transfer request " + iatrS(named.no) + " is being dispatched: wait for it to finish.");
    const dest = { storage: iatrId(named.sl), bin: iatrId(named.bin) };
    const now = fromHolds(dest.bin);
    if (!now.lines.length) return answer(400, "Nothing of this Item Assembly is reserved now: reserve its materials again, or cancel the request.");
    const fp = rrReqFp(now.lines);
    if (fp === iatrS(named.fp)) return answer(200, "Transfer request " + iatrS(named.no) + " already matches this Item Assembly's reservation.", { request: view(named), already: "YES" });
    return { route: "GO", code: "200", message: "", result: {}, lotId: iatrS(named.id), lotNo: iatrS(named.no), fp: fp, rev: (Number(named.rev) || 0) + 1, lines: now.lines.length,
      lineRows: rrLotLines(now.lines, lineCtx(dest)), skipped: now.skipped };
  }
  // CREATE / REPLACE: one open request per IA; CREATE needs the setup on (D12), never after a receipt; REPLACE follows a receipt (D6),
